/*
 * A190803  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 2x-1 and 3x-1 are in a.
 * https://oeis.org/A190803
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 28, u16 n <= 2583, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generation of OEIS A190803:
   a(1)=1; if x∈a then 2·x−1 and 3·x−1 are also in a. */

/* Note: The code uses fixed-size static arrays large enough for all
   terms requested by the tests.  Each array is a simple linear
   container; linear search is used to guarantee correct duplicate
   handling while remaining fast for the problem limits. */

#include <stdlib.h>
#include <stdbool.h>

#define MAX_TERMS 20000          /* should exceed maximum needed n */
#define INITIAL_CAP 512          /* not used now, kept for reference */

/* ------------------------------------------------------------------ */
/* static storage for the sequence, the seen set and the priority heap */
/* ------------------------------------------------------------------ */
static seq_t seq[MAX_TERMS];      /* generated sequence values          */
static size_t seq_len = 0;        /* number of values stored            */

static seq_t seen[MAX_TERMS];     /* all values ever generated          */
static size_t seen_len = 0;       /* number of values in seen          */

static seq_t heap[MAX_TERMS];     /* min‑heap of candidate values      */
static size_t heap_len = 0;       /* current heap size                  */

static bool initialized = false;  /* has the data structures been seed? */

/* ------------------------------------------------------------------ */
/* heap helper functions                                               */
/* ------------------------------------------------------------------ */
static void heap_push(seq_t v)
{
    heap[heap_len] = v;
    size_t i = heap_len;
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent] <= v)
            break;
        heap[i] = heap[parent];
        i = parent;
    }
    heap[i] = v;
    heap_len++;
    if (heap_len > MAX_TERMS)
        abort(); /* safety guard */
}

static seq_t heap_pop(void)
{
    seq_t top = heap[0];
    heap_len--;
    seq_t last = heap[heap_len];
    size_t i = 0;
    while (1) {
        size_t left = (i << 1) + 1;
        if (left >= heap_len)
            break;
        size_t right = left + 1;
        size_t child = (right < heap_len && heap[right] < heap[left]) ? right : left;
        if (heap[child] >= last)
            break;
        heap[i] = heap[child];
        i = child;
    }
    heap[i] = last;
    return top;
}

/* ------------------------------------------------------------------ */
/* helper to test whether a value has already appeared               */
/* ------------------------------------------------------------------ */
static bool seen_contains(seq_t v)
{
    for (size_t i = 0; i < seen_len; ++i)
        if (seen[i] == v)
            return true;
    return false;
}

/* ------------------------------------------------------------------ */
/* initialisation of the data structures (only on first call)          */
/* ------------------------------------------------------------------ */
static void init(void)
{
    if (initialized)
        return;

    /* seed value 1 */
    seq_len = 0;
    seen_len = 0;
    heap_len = 0;

    seq_t one = (seq_t)1;
    seen[seen_len++] = one;
    heap_push(one);

    initialized = true;
}

/* ------------------------------------------------------------------ */
/* Main function that returns the n-th term of the sequence            */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (n == 0) /* invalid index, but guard anyway */
        return (seq_t)0;

    init();

    while (seq_len < (size_t)n) {
        seq_t v = heap_pop();

        /* store the next term of the sequence */
        if (seq_len < MAX_TERMS)
            seq[seq_len++] = v;
        else
            abort(); /* safety guard */

        /* generate the two children */
        seq_t child1 = (seq_t)2 * v - (seq_t)1;
        if (!seen_contains(child1)) {
            if (seen_len < MAX_TERMS)
                seen[seen_len++] = child1;
            else
                abort(); /* safety guard */
            heap_push(child1);
        }

        seq_t child2 = (seq_t)3 * v - (seq_t)1;
        if (!seen_contains(child2)) {
            if (seen_len < MAX_TERMS)
                seen[seen_len++] = child2;
            else
                abort(); /* safety guard */
            heap_push(child2);
        }
    }

    return seq[(size_t)(n - 1)];
}
